-- local runtime only: JT-approved #26/#27 dedicated cleanup role, never runtime DELETE.
CREATE ROLE cj_local_cleanup LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
GRANT USAGE ON SCHEMA public TO cj_local_cleanup;
CREATE TABLE cj_cleanup_operation (
 subject_digest text NOT NULL CHECK(subject_digest ~ '^[0-9a-f]{64}$'),
 operation_id text NOT NULL, confirmation_digest text NOT NULL CHECK(confirmation_digest ~ '^[0-9a-f]{64}$'),
 purpose text NOT NULL CHECK(purpose IN ('account','memory','diagnostics')),
 plan_digest text NOT NULL CHECK(plan_digest ~ '^[0-9a-f]{64}$'),
 plan_bytes bytea CHECK(plan_bytes IS NULL OR plan_digest=encode(sha256(plan_bytes),'hex')),
 registry_bytes bytea NOT NULL, inventory jsonb NOT NULL CHECK(jsonb_typeof(inventory)='array'),
 protocol_versions jsonb NOT NULL CHECK(jsonb_typeof(protocol_versions)='array'),
 targets jsonb NOT NULL CHECK(jsonb_typeof(targets)='array'),
 blocked boolean NOT NULL DEFAULT false, PRIMARY KEY(subject_digest,operation_id)
);
CREATE TABLE cj_cleanup_step (
 subject_digest text NOT NULL,operation_id text NOT NULL,target text NOT NULL,
 invocation_id text NOT NULL,request_digest text NOT NULL CHECK(request_digest ~ '^[0-9a-f]{64}$'),
 request_bytes bytea,
 state text NOT NULL CHECK(state IN ('in_progress','unknown','failed','confirmed')),
 receipt_bytes bytea,
 PRIMARY KEY(subject_digest,operation_id,target),UNIQUE(subject_digest,operation_id,invocation_id),
 FOREIGN KEY(subject_digest,operation_id) REFERENCES cj_cleanup_operation
);
CREATE TABLE cj_cleanup_domain_result (
 subject_digest text NOT NULL,operation_id text NOT NULL,invocation_id text NOT NULL,
 request_digest text NOT NULL CHECK(request_digest ~ '^[0-9a-f]{64}$'),
 receipt_bytes bytea NOT NULL CHECK(octet_length(receipt_bytes) BETWEEN 1 AND 4096),
 PRIMARY KEY(subject_digest,operation_id,invocation_id),
 FOREIGN KEY(subject_digest,operation_id,invocation_id)
 REFERENCES cj_cleanup_step(subject_digest,operation_id,invocation_id)
);
ALTER TABLE cj_cleanup_operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE cj_cleanup_operation FORCE ROW LEVEL SECURITY;
CREATE POLICY cleanup_subject ON cj_cleanup_operation TO cj_local_cleanup USING(subject_digest=nullif(current_setting('cj.cleanup_subject',true),'')) WITH CHECK(subject_digest=nullif(current_setting('cj.cleanup_subject',true),''));
GRANT SELECT,INSERT ON cj_cleanup_operation TO cj_local_cleanup;
ALTER TABLE cj_cleanup_step ENABLE ROW LEVEL SECURITY;
ALTER TABLE cj_cleanup_step FORCE ROW LEVEL SECURITY;
CREATE POLICY cleanup_subject ON cj_cleanup_step TO cj_local_cleanup USING(subject_digest=nullif(current_setting('cj.cleanup_subject',true),'')) WITH CHECK(subject_digest=nullif(current_setting('cj.cleanup_subject',true),''));
GRANT SELECT,INSERT ON cj_cleanup_step TO cj_local_cleanup;
ALTER TABLE cj_cleanup_domain_result ENABLE ROW LEVEL SECURITY;
ALTER TABLE cj_cleanup_domain_result FORCE ROW LEVEL SECURITY;
CREATE POLICY cleanup_subject ON cj_cleanup_domain_result TO cj_local_cleanup USING(subject_digest=nullif(current_setting('cj.cleanup_subject',true),'')) WITH CHECK(subject_digest=nullif(current_setting('cj.cleanup_subject',true),''));
GRANT SELECT,INSERT ON cj_cleanup_domain_result TO cj_local_cleanup;
GRANT UPDATE(blocked,plan_bytes) ON cj_cleanup_operation TO cj_local_cleanup;
GRANT UPDATE(state,receipt_bytes,request_bytes) ON cj_cleanup_step TO cj_local_cleanup;
CREATE FUNCTION cj_cleanup_not_unblocked() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.blocked AND NOT NEW.blocked THEN RAISE EXCEPTION 'cleanup registry gap latched'; END IF;
 IF NEW.plan_bytes IS NOT NULL AND NEW.plan_bytes IS DISTINCT FROM OLD.plan_bytes THEN
  RAISE EXCEPTION 'cleanup selection immutable';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION cj_cleanup_not_unblocked() FROM PUBLIC;
CREATE TRIGGER cleanup_not_unblocked BEFORE UPDATE ON cj_cleanup_operation FOR EACH ROW EXECUTE FUNCTION cj_cleanup_not_unblocked();
CREATE POLICY cj_cleanup_owner ON cj_message_scope FOR SELECT TO cj_local_cleanup USING(scope=nullif(current_setting('cj.cleanup_scope',true),'') AND current_setting('cj.cleanup_purpose',true) IN ('account') AND EXISTS(SELECT 1 FROM cj_cleanup_operation o WHERE o.subject_digest=nullif(current_setting('cj.cleanup_subject',true),'') AND o.operation_id=nullif(current_setting('cj.cleanup_operation',true),'') AND o.purpose=current_setting('cj.cleanup_purpose',true) AND NOT o.blocked));
CREATE POLICY cj_cleanup_delete ON cj_message_scope FOR DELETE TO cj_local_cleanup USING(scope=nullif(current_setting('cj.cleanup_scope',true),'') AND current_setting('cj.cleanup_purpose',true) IN ('account') AND EXISTS(SELECT 1 FROM cj_cleanup_operation o WHERE o.subject_digest=nullif(current_setting('cj.cleanup_subject',true),'') AND o.operation_id=nullif(current_setting('cj.cleanup_operation',true),'') AND o.purpose=current_setting('cj.cleanup_purpose',true) AND NOT o.blocked));
